@st.composite
def gen(draw):
    T = draw(st.integers(1, 4))
    cases = []
    for _ in range(T):
        n = draw(st.integers(2, 5))
        mode = draw(st.integers(0, 3))
        if mode == 0:
            a = draw(st.lists(st.integers(0, 4), min_size=n, max_size=n))
        elif mode == 1:
            v = draw(st.integers(0, 4))
            a = [v] * n
        elif mode == 2:
            a = sorted(draw(st.lists(st.integers(0, 6), min_size=n, max_size=n)))
        else:
            a = sorted(draw(st.lists(st.integers(0, 6), min_size=n, max_size=n)), reverse=True)
        cases.append(f"{n}\n{' '.join(map(str, a))}")
    return f"{T}\n" + "\n".join(cases) + "\n"


def validate(inp):
    lines = inp.strip("\n").split("\n")
    if not lines:
        return False
    try:
        T = int(lines[0])
    except ValueError:
        return False
    if not (1 <= T <= 2 * 10**5):
        return False
    if len(lines) != 1 + 2 * T:
        return False
    total = 0
    for t in range(T):
        nl = lines[1 + 2 * t].strip()
        al = lines[2 + 2 * t].split()
        if not nl.isdigit():
            return False
        n = int(nl)
        if not (2 <= n <= 2 * 10**5):
            return False
        if len(al) != n:
            return False
        total += n
        for x in al:
            if not x.lstrip("-").isdigit():
                return False
            v = int(x)
            if not (0 <= v <= 10**9):
                return False
    return total <= 2 * 10**5


def _feasible(n, a):
    # Operation moves one unit from a later index to an earlier index.
    # Reachable B iff B has the same total S, and every prefix sum of B is
    # >= the corresponding prefix sum of A. Also B must be non-decreasing.
    # Since B_1 >= A_1 >= 0 and B is non-decreasing, all B_i lie in [0, S].
    S = sum(a)
    PA = [0] * (n + 1)
    for i in range(n):
        PA[i + 1] = PA[i] + a[i]

    def dfs(k, last, p):
        # k elements already placed, last value last, prefix sum p
        if k == n:
            return p == S
        rem = n - k
        hi = (S - p) // rem
        for v in range(last, hi + 1):
            p2 = p + v
            if p2 < PA[k + 1]:
                continue
            if dfs(k + 1, v, p2):
                return True
        return False

    return dfs(0, 0, 0)


def ref(inp):
    lines = inp.strip("\n").split("\n")
    T = int(lines[0])
    out = []
    for t in range(T):
        n = int(lines[1 + 2 * t].strip())
        a = [int(x) for x in lines[2 + 2 * t].split()]
        out.append("Yes" if _feasible(n, a) else "No")
    return "\n".join(out)
